    /**
     * Tests getting all ScreeningResults.
     *
     * @return    Collection
     */
    public List<ScreeningResult> testGetAll() throws Throwable {
    LOGGER.info( "ScreeningResultTest:testGetAll() - Retrieving Collection of ScreeningResults:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ScreeningResult : " );
    List<ScreeningResult> collection  = null;

    try {
        // call the static get method on the ScreeningResultService
        collection = service.getAllScreeningResult();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ScreeningResult currEntity  = null;
            Iterator<ScreeningResult> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getScreeningResultId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

